+fn is_validation_environment_artifact(path: &str) -> bool {
+    let normalized = path
+        .replace('\\', "/")
+        .trim_matches('/')
+        .to_ascii_lowercase();
+    normalized.split('/').any(|component| {
+        matches!(
+            component,
+            ".venv" | "venv" | "node_modules" | "target" | "__pycache__" | ".pytest_cache"
+        )
+    }) || exact_pip_cache_artifact_path(&normalized)
