+fn read_repair_context_file(project: &Path, path: &str) -> Result<Vec<u8>> {
+    let relative = Path::new(path);
+    if path.is_empty()
+        || path.contains('\\')
+        || relative
+            .components()
+            .any(|component| !matches!(component, Component::Normal(_)))
+    {
+        bail!("Repair context retrieval path is invalid");
+    }
