+        }
+        let (mut file, metadata) = open_windows_recovery_file(&full)?;
+        if metadata.len() > REPAIR_CONTEXT_TEXT_CLASSIFICATION_LIMIT {
+            bail!("Repair context file exceeds its bounded retrieval size");
