+fn review_png_has_exact_end(bytes: &[u8]) -> bool {
+    if !bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
+        return false;
+    }
+    let mut offset = 8usize;
+    while offset.checked_add(12).is_some_and(|end| end <= bytes.len()) {
+        let length = u32::from_be_bytes([
+            bytes[offset],
+            bytes[offset + 1],
+            bytes[offset + 2],
+            bytes[offset + 3],
+        ]) as usize;
+        let Some(end) = offset
+            .checked_add(12)
+            .and_then(|value| value.checked_add(length))
+        else {
+            return false;
+        };
+        if end > bytes.len() {
+            return false;
+        }
+        if &bytes[offset + 4..offset + 8] == b"IEND" {
+            return length == 0 && end == bytes.len();
+        }
+        offset = end;
+    }
+    false
+}
+
+fn review_jpeg_has_exact_end(bytes: &[u8]) -> bool {
+    if !bytes.starts_with(&[0xff, 0xd8]) {
+        return false;
+    }
+    let mut offset = 2usize;
+    let mut in_scan = false;
+    while offset < bytes.len() {
+        if bytes[offset] != 0xff {
+            if in_scan {
+                offset += 1;
+                continue;
+            }
+            return false;
+        }
+        let marker_start = offset;
+        while offset < bytes.len() && bytes[offset] == 0xff {
+            offset += 1;
+        }
+        if offset >= bytes.len() {
+            return false;
+        }
+        let marker = bytes[offset];
+        offset += 1;
+        if in_scan {
+            if marker == 0x00 || (0xd0..=0xd7).contains(&marker) {
+                continue;
+            }
+            in_scan = false;
+        }
+        match marker {
+            0xd9 => return offset == bytes.len(),
+            0xd8 | 0x00 => return false,
+            0x01 | 0xd0..=0xd7 => continue,
+            _ => {
+                if offset + 2 > bytes.len() {
+                    return false;
+                }
+                let length = u16::from_be_bytes([bytes[offset], bytes[offset + 1]]) as usize;
+                if length < 2
+                    || offset
+                        .checked_add(length)
+                        .is_none_or(|end| end > bytes.len())
+                {
+                    return false;
+                }
+                offset += length;
+                if marker == 0xda {
+                    in_scan = true;
+                }
+            }
+        }
+        if offset <= marker_start {
+            return false;
+        }
+    }
+    false
+}
