+#!/usr/bin/env python3
+"""Run a credential-reduced local Codex worker in an isolated Git worktree."""
+
+from __future__ import annotations
+
+import argparse
+import hashlib
+import json
+import os
+import re
+import secrets
+import select
+import signal
+import stat
+import subprocess
+import sys
+import time
+from datetime import datetime, timezone
+from pathlib import Path
+from urllib.request import ProxyHandler, build_opener
+
+
+PROVIDER_ID = "local_qwen"
+MODEL_ID = "qwen36-local"
+BASE_URL = "http://127.0.0.1:8080/v1"
+CONTEXT_WINDOW = 262_144
+EXPECTED_MODEL_PARAMETERS = 35_505_251_456
+EXPECTED_MODEL_FTYPE = "IQ4_XS - 4.25 bpw"
+EXPECTED_MODEL_FILENAME = "Qwen_Qwen3.6-35B-A3B-IQ4_XS.gguf"
+# llama.cpp exposes the loaded template through /props without the file's final newline.
+EXPECTED_TEMPLATE_SHA256 = "e409e9daee03f51b2612d96f0a253027baec06abd1c2429e184380479662d416"
+MAX_UNTRACKED_FILES = 128
+MAX_UNTRACKED_FILE_BYTES = 2 * 1024 * 1024
+MAX_REVIEW_PATCH_BYTES = 8 * 1024 * 1024
+MAX_STATUS_BYTES = 1024 * 1024
+EVIDENCE_TIMEOUT_SECONDS = 30
+WORKTREE_NAME = re.compile(r"^[a-z0-9][a-z0-9-]{0,63}$")
+SENSITIVE_ENV_PARTS = (
+    "API_KEY",
+    "AUTH",
+    "COOKIE",
+    "CREDENTIAL",
+    "PASSWORD",
+    "PASSWD",
+    "SECRET",
+    "TOKEN",
+)
+UNTRUSTED_ENV_PREFIXES = (
+    "AWS_",
+    "AZURE_",
+    "CODEX_",
+    "GH_",
+    "GIT_",
+    "GOOGLE_",
+    "OPENAI_",
+    "SSH_",
+)
+
+
+def run_checked(command: list[str], *, cwd: Path) -> str:
+    return subprocess.check_output(command, cwd=cwd, text=True).strip()
+
+
+def repository_root() -> Path:
+    return Path(run_checked(["git", "rev-parse", "--show-toplevel"], cwd=Path.cwd())).resolve()
+
+
+def default_run_name() -> str:
+    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
+    return f"task-{stamp}-{secrets.token_hex(2)}"
+
+
+def validate_run_name(value: str) -> str:
+    if not WORKTREE_NAME.fullmatch(value):
+        raise argparse.ArgumentTypeError(
+            "worktree name must be lowercase letters, digits, or hyphens (maximum 64 characters)"
+        )
+    return value
+
+
+def sanitized_environment(state_dir: Path) -> dict[str, str]:
+    environment = {
+        key: value
+        for key, value in os.environ.items()
+        if not any(part in key.upper() for part in SENSITIVE_ENV_PARTS)
+        and not key.upper().startswith(UNTRUSTED_ENV_PREFIXES)
+    }
+    original_home = Path(os.environ.get("HOME", ""))
+    worker_home = state_dir / "home"
+    worker_tmp = state_dir / "tmp"
+    worker_home.mkdir(parents=True, exist_ok=True)
+    worker_tmp.mkdir(parents=True, exist_ok=True)
+    environment.update(
+        {
+            "CODEX_HOME": str(state_dir / "codex-home"),
+            "HOME": str(worker_home),
+            "CARGO_HOME": str(worker_home / ".cargo"),
+            "TMPDIR": str(worker_tmp),
+            "GIT_CONFIG_GLOBAL": "/dev/null",
+            "GIT_CONFIG_NOSYSTEM": "1",
+            "GIT_TERMINAL_PROMPT": "0",
+            "GIT_OPTIONAL_LOCKS": "0",
+            "NO_COLOR": "1",
+        }
+    )
+    rustup_home = original_home / ".rustup"
+    if rustup_home.is_dir():
+        environment["RUSTUP_HOME"] = str(rustup_home)
+    Path(environment["CODEX_HOME"]).mkdir(parents=True, exist_ok=True)
+    return environment
+
+
+def toml_string(value: str) -> str:
+    return json.dumps(value)
+
+
+def write_permission_config(root: Path, worktree: Path, state_dir: Path) -> Path:
+    config_path = state_dir / "codex-home" / "config.toml"
+    filesystem_rules = {
+        ":minimal": "read",
+        "/opt/homebrew": "read",
+        "/Applications/Xcode.app": "read",
+        "/Library/Developer": "read",
+        str(root): "deny",
+        str(worktree): "write",
+        str(worktree / ".git"): "read",
+        str(state_dir): "write",
+        str(state_dir / "repository.git"): "read",
+    }
+    original_home = Path(os.environ.get("HOME", ""))
+    for runtime_path in (original_home / ".cargo" / "bin", original_home / ".rustup"):
+        if runtime_path.is_dir():
+            filesystem_rules[str(runtime_path)] = "read"
+    lines = [
+        'default_permissions = "local_worker"',
+        "",
+        "[permissions.local_worker]",
+        'description = "Isolated Assemblywright local proposal worker"',
+        "",
+        "[permissions.local_worker.filesystem]",
+    ]
+    lines.extend(
+        f"{toml_string(path)} = {toml_string(access)}"
+        for path, access in filesystem_rules.items()
+    )
+    lines.extend(
+        [
+            "",
+            "[permissions.local_worker.network]",
+            "enabled = false",
+            "",
+        ]
+    )
+    config_path.write_text("\n".join(lines), encoding="utf-8")
+    config_path.chmod(0o600)
+    return config_path
+
+
+def codex_command(worktree: Path, state_dir: Path) -> list[str]:
+    worker_home = state_dir / "home"
+    worker_tmp = state_dir / "tmp"
+    shell_values = {
+        "HOME": str(worker_home),
