+        "GIT_CONFIG_NOSYSTEM": "1",
+        "GIT_TERMINAL_PROMPT": "0",
+        "GIT_OPTIONAL_LOCKS": "0",
+        "NO_COLOR": "1",
+    }
+    original_home = Path(os.environ.get("HOME", ""))
+    if (original_home / ".rustup").is_dir():
+        shell_values["RUSTUP_HOME"] = str(original_home / ".rustup")
+
+    command = [
+        "codex",
+        "exec",
+        "-C",
+        str(worktree),
+        "--ephemeral",
+        "--strict-config",
+        "--color",
+        "never",
+        "--enable",
+        "skip_host_skill_discovery",
+        "--disable",
+        "plugins",
+        "--disable",
+        "apps",
+        "--disable",
+        "browser_use",
+        "--disable",
+        "browser_use_external",
+        "--disable",
+        "memories",
+        "--disable",
+        "skill_search",
+        "--disable",
+        "skill_mcp_dependency_install",
+        "--disable",
+        "hooks",
+        "-o",
+        str(state_dir / "last-message.txt"),
+        "-c",
+        'approval_policy="never"',
+        "-c",
