+def verify_permission_profile(
+    root: Path,
+    worktree: Path,
+    state_dir: Path,
+    environment: dict[str, str],
+) -> None:
+    probe_path = state_dir / "sandbox-preflight"
+    program = """
+if /usr/bin/head -c 1 "$1" >/dev/null 2>&1; then exit 21; fi
+/usr/bin/head -c 1 "$2" >/dev/null || exit 22
+/usr/bin/touch "$3" || exit 23
+/bin/rm "$3" || exit 24
+if /usr/bin/curl --silent --max-time 1 http://127.0.0.1:8080/health >/dev/null 2>&1; then exit 25; fi
+if /usr/bin/head -c 1 "$4" >/dev/null 2>&1; then exit 26; fi
+if /usr/bin/head -c 1 "$5" >/dev/null 2>&1; then exit 27; fi
+/usr/bin/git -C "$6" status --short >/dev/null || exit 28
+"""
+    result = subprocess.run(
+        [
+            "codex",
+            "sandbox",
+            "-P",
+            "local_worker",
+            "-C",
+            str(worktree),
+            "/bin/zsh",
+            "-c",
+            program,
+            "local-worker-preflight",
+            str(root / "AGENTS.md"),
+            str(worktree / "AGENTS.md"),
+            str(probe_path),
+            str(root / ".git" / "index"),
+            str(root / ".git" / "config"),
+            str(worktree),
+        ],
+        env=environment,
+        check=False,
+        stdout=subprocess.DEVNULL,
+        stderr=subprocess.PIPE,
+        text=True,
+        timeout=30,
+    )
+    if result.returncode != 0:
+        detail = result.stderr.strip()
+        suffix = f": {detail}" if detail else ""
