+def validate_endpoint_payloads(models: dict, props: dict) -> None:
+    matching_models = [item for item in models.get("data", []) if item.get("id") == MODEL_ID]
+    if len(matching_models) != 1:
+        raise RuntimeError(f"model catalog must advertise exactly one {MODEL_ID}")
+    metadata = matching_models[0].get("meta", {})
+    if metadata.get("n_ctx") != CONTEXT_WINDOW:
+        raise RuntimeError("local Qwen context window does not match the pinned configuration")
+    if metadata.get("n_params") != EXPECTED_MODEL_PARAMETERS:
+        raise RuntimeError("local Qwen parameter count does not match the pinned model")
+    if metadata.get("ftype") != EXPECTED_MODEL_FTYPE:
+        raise RuntimeError("local Qwen quantization does not match the pinned model")
+
+    template = props.get("chat_template")
+    if not isinstance(template, str):
+        raise RuntimeError("llama.cpp /props did not return the loaded chat template")
+    template_sha256 = hashlib.sha256(template.encode("utf-8")).hexdigest()
+    if template_sha256 != EXPECTED_TEMPLATE_SHA256:
+        raise RuntimeError("llama.cpp is not using the pinned Codex-compatible Qwen template")
+    if props.get("model_alias") != MODEL_ID:
+        raise RuntimeError("llama.cpp model alias does not match the pinned route")
+    if props.get("model_ftype") != EXPECTED_MODEL_FTYPE:
+        raise RuntimeError("llama.cpp runtime quantization does not match the pinned route")
+    if Path(str(props.get("model_path", ""))).name != EXPECTED_MODEL_FILENAME:
+        raise RuntimeError("llama.cpp runtime model file does not match the pinned route")
+    if props.get("total_slots") != 1:
+        raise RuntimeError("llama.cpp must expose exactly one bounded inference slot")
+
