+def ensure_private_directory(path: Path) -> None:
+    if os.path.lexists(path):
+        details = path.lstat()
+        if stat.S_ISLNK(details.st_mode) or not stat.S_ISDIR(details.st_mode):
+            raise RuntimeError(f"worker state path is not an ordinary directory: {path}")
+        if details.st_uid != os.getuid():
+            raise RuntimeError(f"worker state directory has the wrong owner: {path}")
+        if stat.S_IMODE(details.st_mode) & 0o077:
+            raise RuntimeError(f"worker state directory must have mode 0700: {path}")
+        return
+    path.mkdir(mode=0o700)
+
+
+def create_worktree(root: Path, run_name: str) -> tuple[Path, Path]:
+    root = root.resolve()
+    workers_dir = root / ".codex-workers"
+    if subprocess.run(
+        ["git", "check-ignore", "-q", ".codex-workers/"], cwd=root, check=False
+    ).returncode != 0:
+        raise RuntimeError(".codex-workers/ must be ignored before launching a local worker")
+    ensure_private_directory(workers_dir)
+    state_root = workers_dir / ".state"
+    ensure_private_directory(state_root)
+    if workers_dir.resolve() != root / ".codex-workers":
+        raise RuntimeError("worker directory escaped the repository root")
+    if state_root.resolve().parent != workers_dir.resolve():
+        raise RuntimeError("worker state directory escaped the worker root")
+
+    worktree = workers_dir / run_name
+    state_dir = state_root / run_name
+    if os.path.lexists(worktree) or os.path.lexists(state_dir):
+        raise RuntimeError(f"worker path already exists: {run_name}")
+    state_dir.mkdir(mode=0o700)
+    bundle_path = state_dir / "snapshot.bundle"
+    bare_repository = state_dir / "repository.git"
+    subprocess.run(
+        ["git", "bundle", "create", str(bundle_path), "HEAD"],
+        cwd=root,
+        check=True,
+    )
+    subprocess.run(
+        ["git", "init", "--bare", "--initial-branch=snapshot", str(bare_repository)],
+        cwd=root,
+        check=True,
+        stdout=subprocess.DEVNULL,
+    )
+    subprocess.run(
+        [
+            "git",
+            "-C",
+            str(bare_repository),
+            "fetch",
+            "--no-tags",
+            str(bundle_path),
+            "HEAD:refs/heads/snapshot",
+        ],
+        cwd=root,
+        check=True,
+        stdout=subprocess.DEVNULL,
+    )
+    subprocess.run(
+        ["git", "-C", str(bare_repository), "worktree", "add", "--detach", str(worktree), "HEAD"],
+        cwd=root,
+        check=True,
+    )
+    bundle_path.unlink()
+    if worktree.is_symlink() or not worktree.is_dir():
+        raise RuntimeError("git created an invalid worker directory")
+    if worktree.resolve().parent != workers_dir.resolve():
+        raise RuntimeError("git worktree escaped the worker root")
+    return worktree, state_dir
+
