+def descendant_pids(root_pid: int) -> set[int]:
+    try:
+        output = subprocess.check_output(
+            ["ps", "-axo", "pid=,ppid="], text=True, timeout=5
+        )
+    except (subprocess.SubprocessError, OSError):
+        return set()
+    children: dict[int, list[int]] = {}
+    for line in output.splitlines():
+        fields = line.split()
+        if len(fields) != 2:
+            continue
+        pid, parent = (int(value) for value in fields)
+        children.setdefault(parent, []).append(pid)
+    descendants: set[int] = set()
+    pending = list(children.get(root_pid, []))
+    while pending:
+        pid = pending.pop()
+        if pid in descendants:
+            continue
+        descendants.add(pid)
+        pending.extend(children.get(pid, []))
+    return descendants
+
+
+def signal_processes(pids: set[int], signum: signal.Signals) -> None:
+    for pid in sorted(pids, reverse=True):
+        try:
+            os.kill(pid, signum)
+        except ProcessLookupError:
+            pass
+
+
+def pids_with_cwd_under(root: Path) -> set[int]:
+    try:
+        output = subprocess.check_output(
+            ["/usr/sbin/lsof", "-n", "-P", "-a", "-d", "cwd", "-F", "pn"],
+            text=True,
+            timeout=10,
+            stderr=subprocess.DEVNULL,
+        )
+    except (subprocess.SubprocessError, OSError):
+        return set()
+    root = root.resolve()
+    matches: set[int] = set()
+    current_pid: int | None = None
+    for line in output.splitlines():
+        if line.startswith("p") and line[1:].isdigit():
+            current_pid = int(line[1:])
+        elif line.startswith("n") and current_pid is not None:
+            try:
+                Path(line[1:]).resolve().relative_to(root)
+            except (OSError, ValueError):
+                continue
+            matches.add(current_pid)
+    return matches
+
+
+class ProcessTreeMonitor:
+    """Track descendants across fork, setsid, reparenting, and parent exit on macOS."""
+
+    def __init__(self, root_pid: int, containment_root: Path) -> None:
+        self.root_pid = root_pid
+        self.containment_root = containment_root.resolve()
+        self.observed: set[int] = {root_pid}
+        self.last_scan = 0.0
+        self.queue = None
+        if hasattr(select, "kqueue"):
+            self.queue = select.kqueue()
+            try:
+                event = select.kevent(
+                    root_pid,
+                    filter=select.KQ_FILTER_PROC,
+                    flags=select.KQ_EV_ADD | select.KQ_EV_ENABLE,
+                    fflags=(
+                        select.KQ_NOTE_EXIT
+                        | select.KQ_NOTE_FORK
+                        | select.KQ_NOTE_TRACK
+                        | select.KQ_NOTE_TRACKERR
+                    ),
+                )
+                self.queue.control([event], 0, 0)
+            except OSError:
+                self.queue.close()
+                self.queue = select.kqueue()
+                event = select.kevent(
+                    root_pid,
+                    filter=select.KQ_FILTER_PROC,
+                    flags=select.KQ_EV_ADD | select.KQ_EV_ENABLE,
+                    fflags=select.KQ_NOTE_EXIT | select.KQ_NOTE_FORK,
+                )
+                self.queue.control([event], 0, 0)
+
+    def poll(self, timeout: float = 0, force_scan: bool = False) -> set[int]:
+        events = []
+        if self.queue is not None:
+            events = self.queue.control(None, 1024, timeout)
+            for event in events:
+                self.observed.add(int(event.ident))
+        else:
+            if timeout:
+                time.sleep(timeout)
+        now = time.monotonic()
+        if force_scan or events or now - self.last_scan >= 0.5:
+            self.observed.update(descendant_pids(self.root_pid))
+            self.observed.update(pids_with_cwd_under(self.containment_root))
+            self.last_scan = now
+        return set(self.observed)
+
+    def close(self) -> None:
+        if self.queue is not None:
+            self.queue.close()
+
+
+def terminate_process_tree(
+    process: subprocess.Popen,
+    monitor: ProcessTreeMonitor,
+    grace_seconds: int = 10,
+) -> None:
+    if process.poll() is None:
+        try:
+            os.killpg(process.pid, signal.SIGSTOP)
+        except ProcessLookupError:
+            pass
+
+    descendants = monitor.poll(0, force_scan=True) - {process.pid}
+    signal_processes(descendants, signal.SIGSTOP)
+    stable_passes = 0
+    for _ in range(8):
+        current = (monitor.poll(0, force_scan=True) | descendant_pids(process.pid)) - {
+            process.pid
+        }
+        signal_processes(current - descendants, signal.SIGSTOP)
+        if current == descendants:
+            stable_passes += 1
+            if stable_passes >= 2:
+                break
+        else:
+            stable_passes = 0
+            descendants.update(current)
+
+    signal_processes(descendants, signal.SIGTERM)
+    try:
+        os.killpg(process.pid, signal.SIGTERM)
+    except ProcessLookupError:
+        pass
+    signal_processes(descendants, signal.SIGCONT)
+    try:
+        os.killpg(process.pid, signal.SIGCONT)
+    except ProcessLookupError:
+        pass
+    try:
+        deadline = time.monotonic() + grace_seconds
+        while time.monotonic() < deadline:
+            wait_time = max(0, min(0.1, deadline - time.monotonic()))
+            current = monitor.poll(wait_time) - {process.pid}
+            new_descendants = current - descendants
+            if new_descendants:
+                descendants.update(new_descendants)
+                signal_processes(new_descendants, signal.SIGTERM)
+            if process.poll() is not None and not any_process_exists(descendants):
+                break
+    except (OSError, ValueError):
+        pass
+
+    # Freeze any late forks before the final kill pass.
+    for _ in range(4):
+        current = monitor.poll(0, force_scan=True) - {process.pid}
+        signal_processes(current, signal.SIGSTOP)
+        descendants.update(current)
+
+    signal_processes(descendants, signal.SIGKILL)
+    try:
+        os.killpg(process.pid, signal.SIGKILL)
+    except ProcessLookupError:
+        pass
+    try:
+        process.wait(timeout=5)
+    except subprocess.TimeoutExpired:
+        pass
+
+
+def any_process_exists(pids: set[int]) -> bool:
+    for pid in pids:
+        try:
+            os.kill(pid, 0)
+            return True
+        except ProcessLookupError:
+            continue
+        except PermissionError:
+            return True
+    return False
+
+
+def capture_bounded(
+    command: list[str],
+    *,
+    cwd: Path,
+    max_bytes: int,
+    timeout: int = EVIDENCE_TIMEOUT_SECONDS,
+    allowed_returncodes: tuple[int, ...] = (0,),
+) -> bytes:
+    """Capture command output without allowing evidence generation to exhaust resources."""
+    process = subprocess.Popen(
+        command,
+        cwd=cwd,
+        stdout=subprocess.PIPE,
+        stderr=subprocess.PIPE,
+        start_new_session=True,
+    )
+    monitor = ProcessTreeMonitor(process.pid, cwd)
+    assert process.stdout is not None
+    assert process.stderr is not None
+    stdout_buffer = bytearray()
+    stderr_buffer = bytearray()
+    streams = {
+        process.stdout.fileno(): (process.stdout, stdout_buffer),
+        process.stderr.fileno(): (process.stderr, stderr_buffer),
+    }
+    deadline = time.monotonic() + timeout
+    total = 0
+    try:
+        while streams:
+            remaining = deadline - time.monotonic()
+            if remaining <= 0:
+                raise TimeoutError(f"evidence command exceeded {timeout} seconds: {command[0]}")
+            ready, _, _ = select.select(list(streams), [], [], min(remaining, 0.25))
+            if not ready and process.poll() is not None:
+                ready = list(streams)
+            for descriptor in ready:
+                stream, output = streams[descriptor]
+                chunk = os.read(descriptor, 64 * 1024)
+                if not chunk:
+                    stream.close()
+                    del streams[descriptor]
+                    continue
+                total += len(chunk)
+                if total > max_bytes:
+                    raise RuntimeError(
+                        f"evidence command exceeded the {max_bytes}-byte limit: {command[0]}"
+                    )
+                output.extend(chunk)
+        returncode = process.wait(timeout=max(1, int(deadline - time.monotonic())))
+    except BaseException:
+        terminate_process_tree(process, monitor, grace_seconds=1)
+        for stream, _ in streams.values():
+            stream.close()
+        monitor.close()
+        raise
+
+    terminate_process_tree(process, monitor, grace_seconds=1)
+    monitor.close()
+    if returncode not in allowed_returncodes:
+        detail = bytes(stderr_buffer).decode("utf-8", errors="replace").strip()
+        suffix = f": {detail}" if detail else ""
+        raise RuntimeError(
+            f"evidence command failed with exit {returncode}: {' '.join(command)}{suffix}"
+        )
+    return bytes(stdout_buffer)
+
+
+def run_worker(
+    command: list[str],
+    prompt: str,
+    environment: dict[str, str],
+    timeout: int,
+    containment_root: Path | None = None,
+) -> int:
+    containment_root = (containment_root or Path.cwd()).resolve()
+    wrapped_command = [
+        "/bin/zsh",
+        "-c",
+        'kill -STOP $$; exec "$@"',
+        "local-worker-supervisor",
+        *command,
+    ]
+    process = subprocess.Popen(
+        wrapped_command,
+        env=environment,
+        stdin=subprocess.PIPE,
+        text=True,
+        start_new_session=True,
+        cwd=containment_root,
+    )
+    stopped_pid, stopped_status = os.waitpid(process.pid, os.WUNTRACED)
+    if stopped_pid != process.pid or not os.WIFSTOPPED(stopped_status):
+        process.kill()
+        process.wait()
+        raise RuntimeError("could not suspend the local worker before process-tree tracking")
+    monitor = ProcessTreeMonitor(process.pid, containment_root)
+    interrupted_signal: int | None = None
+    previous_handlers: dict[signal.Signals, object] = {}
+
+    def handle_signal(signum: int, _frame: object) -> None:
+        nonlocal interrupted_signal
+        interrupted_signal = signum
+        raise KeyboardInterrupt
+
+    for signum in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP):
+        previous_handlers[signum] = signal.getsignal(signum)
+        signal.signal(signum, handle_signal)
+    try:
+        os.killpg(process.pid, signal.SIGCONT)
+        assert process.stdin is not None
+        process.stdin.write(prompt)
+        process.stdin.close()
+        deadline = time.monotonic() + timeout
+        while process.poll() is None:
+            remaining = deadline - time.monotonic()
+            if remaining <= 0:
+                raise subprocess.TimeoutExpired(command, timeout)
+            monitor.poll(min(0.1, remaining))
+        result = process.returncode
+        terminate_process_tree(process, monitor, grace_seconds=1)
+        return result
+    except subprocess.TimeoutExpired:
+        terminate_process_tree(process, monitor)
+        duration = f"{timeout // 60} minutes" if timeout >= 60 else f"{timeout} seconds"
+        print(f"Local worker exceeded {duration}.", file=sys.stderr)
+        return 124
+    except KeyboardInterrupt:
+        terminate_process_tree(process, monitor)
+        signum = interrupted_signal or signal.SIGINT
+        print(f"Local worker cancelled by signal {signum}.", file=sys.stderr)
+        return 128 + signum
+    finally:
+        monitor.close()
+        for signum, handler in previous_handlers.items():
+            signal.signal(signum, handler)
+
+
+def validate_untracked_file(worktree: Path, encoded_path: bytes) -> str:
+    path_text = os.fsdecode(encoded_path)
+    relative = Path(path_text)
+    if relative.is_absolute() or not relative.parts or any(
+        part in ("", ".", "..") for part in relative.parts
+    ):
+        raise RuntimeError(f"unsafe untracked path: {path_text!r}")
+
+    candidate = worktree
+    for index, part in enumerate(relative.parts):
+        candidate /= part
+        details = candidate.lstat()
+        if stat.S_ISLNK(details.st_mode):
+            raise RuntimeError(f"untracked symlinks are not admitted to review evidence: {path_text}")
+        if index < len(relative.parts) - 1 and not stat.S_ISDIR(details.st_mode):
+            raise RuntimeError(f"untracked path has a non-directory parent: {path_text}")
+    details = candidate.lstat()
+    if not stat.S_ISREG(details.st_mode):
+        raise RuntimeError(f"untracked path is not an ordinary file: {path_text}")
+    if details.st_size > MAX_UNTRACKED_FILE_BYTES:
+        raise RuntimeError(
+            f"untracked file exceeds the {MAX_UNTRACKED_FILE_BYTES}-byte limit: {path_text}"
+        )
+    return path_text
+
+
+def build_review_patch(worktree: Path, state_dir: Path) -> Path:
+    patch_path = state_dir / "review.patch"
+    tracked = capture_bounded(
+        ["git", "diff", "HEAD", "--binary", "--no-ext-diff", "--no-textconv"],
+        cwd=worktree,
+        max_bytes=MAX_REVIEW_PATCH_BYTES,
+    )
+    untracked_output = capture_bounded(
+        ["git", "ls-files", "--others", "--exclude-standard", "-z"],
+        cwd=worktree,
+        max_bytes=MAX_STATUS_BYTES,
+    )
+    untracked = [item for item in untracked_output.split(b"\0") if item]
+    if len(untracked) > MAX_UNTRACKED_FILES:
+        raise RuntimeError(f"worker created more than {MAX_UNTRACKED_FILES} untracked files")
+    patch = bytearray(tracked)
+    for encoded_path in untracked:
+        path = validate_untracked_file(worktree, encoded_path)
+        remaining = MAX_REVIEW_PATCH_BYTES - len(patch)
+        if remaining <= 0:
+            raise RuntimeError(
+                f"review patch exceeds the {MAX_REVIEW_PATCH_BYTES}-byte limit"
+            )
+        rendered = capture_bounded(
+            [
+                "git",
+                "diff",
+                "--binary",
+                "--no-ext-diff",
+                "--no-textconv",
+                "--no-index",
+                "--",
+                "/dev/null",
+                path,
+            ],
+            cwd=worktree,
+            max_bytes=remaining,
+            allowed_returncodes=(0, 1),
+        )
+        patch.extend(rendered)
+    patch_path.write_bytes(patch)
+    return patch_path
+
+
+def report_worktree(worktree: Path, state_dir: Path) -> None:
+    print(f"\nLocal worker worktree: {worktree}")
+    print("\nStatus:")
+    sys.stdout.flush()
+    status = capture_bounded(
+        ["git", "status", "--short"], cwd=worktree, max_bytes=MAX_STATUS_BYTES
+    )
+    sys.stdout.buffer.write(status)
+    sys.stdout.buffer.flush()
+    print("\nDiff stat:")
+    sys.stdout.flush()
+    diff_stat = capture_bounded(
+        ["git", "diff", "HEAD", "--stat", "--no-ext-diff", "--no-textconv"],
+        cwd=worktree,
+        max_bytes=MAX_STATUS_BYTES,
+    )
+    sys.stdout.buffer.write(diff_stat)
+    sys.stdout.buffer.flush()
+    print("\nDiff check:")
+    capture_bounded(
+        ["git", "diff", "HEAD", "--check", "--no-ext-diff", "--no-textconv"],
+        cwd=worktree,
+        max_bytes=MAX_STATUS_BYTES,
+    )
+    print("git diff HEAD --check exit: 0")
+    patch_path = build_review_patch(worktree, state_dir)
+    print(f"Complete tracked and untracked review patch: {patch_path}")
+    print("\nNo changes were integrated, staged, committed, or pushed.")
+
+
+def parse_args() -> argparse.Namespace:
+    parser = argparse.ArgumentParser()
+    task = parser.add_mutually_exclusive_group(required=True)
+    task.add_argument("--task")
+    task.add_argument("--task-file", type=Path)
+    parser.add_argument("--name", type=validate_run_name)
+    parser.add_argument("--timeout-minutes", type=int, default=60)
+    parser.add_argument("--dry-run", action="store_true")
+    return parser.parse_args()
+
+
+def main() -> int:
+    args = parse_args()
+    if args.timeout_minutes < 1 or args.timeout_minutes > 240:
+        raise SystemExit("--timeout-minutes must be between 1 and 240")
+    task = args.task if args.task is not None else args.task_file.read_text(encoding="utf-8")
+    task = task.strip()
+    if not task:
+        raise SystemExit("task must not be empty")
+    if len(task) > 20_000:
+        raise SystemExit("task exceeds 20,000 characters")
+
+    root = repository_root()
+    run_name = args.name or default_run_name()
+    prospective_worktree = root / ".codex-workers" / run_name
+    prospective_state = root / ".codex-workers" / ".state" / run_name
+    if args.dry_run:
+        print(
+            json.dumps(
+                {
+                    "base_ref": "HEAD",
+                    "base_url": BASE_URL,
+                    "model": MODEL_ID,
+                    "provider": PROVIDER_ID,
+                    "worktree": str(prospective_worktree),
+                    "command": codex_command(prospective_worktree, prospective_state),
+                },
+                indent=2,
+            )
+        )
+        return 0
+
+    verify_endpoint()
+    worktree, state_dir = create_worktree(root, run_name)
+    environment = sanitized_environment(state_dir)
+    write_permission_config(root, worktree, state_dir)
+    verify_permission_profile(root, worktree, state_dir, environment)
+    print(f"Local Qwen worker: {MODEL_ID} via {BASE_URL}", flush=True)
+    print(
+        f"Detached base: {run_checked(['git', 'rev-parse', 'HEAD'], cwd=worktree)}",
+        flush=True,
+    )
+    print(f"Worktree: {worktree}", flush=True)
+    print("Parent working-tree changes are intentionally not included.", flush=True)
+    result = run_worker(
+        codex_command(worktree, state_dir),
+        worker_prompt(task),
+        environment,
+        args.timeout_minutes * 60,
+        containment_root=worktree,
+    )
+    report_worktree(worktree, state_dir)
+    return result
+
+
+if __name__ == "__main__":
+    raise SystemExit(main())

